1	export interface Item {
2	  readonly type: string;
3	  readonly material?: string;
4	  readonly enchantment?: number;
5	  readonly cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  readonly op: "quote";
10	  readonly items: readonly Item[];
11	}
12	
13	export interface Damage {
14	  readonly itemType: string;
15	  readonly amount: number;
16	}
17	
18	export interface Incident {
19	  readonly cause: string;
20	  readonly damages: readonly Damage[];
21	}
22	
23	export interface ClaimStep {
24	  readonly op: "claim";
25	  readonly policy: number;
26	  readonly incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  readonly yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  readonly customer: Customer;
37	  readonly steps: readonly Step[];
38	}
39	
40	export interface QuoteResult {
41	  readonly premium: number;
42	}
43	
44	export interface ClaimResult {
45	  readonly payout: number;
46	  readonly remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  readonly results: readonly StepResult[];
53	}
54	
55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const isKnownItemType = (type: string): boolean =>
68	  type in BASE_PREMIUM_BY_ITEM_TYPE;
69	
70	const rejectUnknownItemTypes = (items: readonly Item[]): void => {
71	  const unknownItem = items.find((item) => !isKnownItemType(item.type));
72	
73	  if (unknownItem !== undefined) {
74	    throw new Error(`Unknown item type: ${unknownItem.type}`);
75	  }
76	};
77	
78	const itemBasePremiumOf = (item: Item): number =>
79	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
80	
81	const BLOCK_PREMIUM = 60;
82	const BLOCK_SIZE = 3;
83	
84	const itemTypesOf = (items: readonly Item[]): readonly string[] => [
85	  ...new Set(items.map((item) => item.type)),
86	];
87	
88	const itemsGroupedByType = (
89	  items: readonly Item[],
90	): readonly (readonly Item[])[] =>
91	  itemTypesOf(items).map((type) => items.filter((item) => item.type === type));
92	
93	// A component block is a discount on exactly BLOCK_SIZE items of the same type.
94	const sameTypeBasePremiumOf = (sameTypeItems: readonly Item[]): number =>
95	  sameTypeItems.length === BLOCK_SIZE
96	    ? BLOCK_PREMIUM
97	    : sumOf(sameTypeItems, itemBasePremiumOf);
98	
99	const CURSED_SURCHARGE_RATE = 0.5;
100	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
101	const HIGH_ENCHANTMENT_THRESHOLD = 5;
102	
103	const isCursed = (item: Item): boolean => item.cursed === true;
104	
105	const isHighlyEnchanted = (item: Item): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	interface Surcharge {
109	  readonly appliesTo: (item: Item) => boolean;
110	  readonly rate: number;
111	}
112	
113	const SURCHARGES: readonly Surcharge[] = [
114	  { appliesTo: isCursed, rate: CURSED_SURCHARGE_RATE },
115	  { appliesTo: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
116	];
117	
118	const surchargeRateOf = (item: Item): number =>
119	  sumOf(SURCHARGES, (surcharge) =>
120	    surcharge.appliesTo(item) ? surcharge.rate : 0,
121	  );
122	
123	const itemSurchargeOf = (item: Item): number =>
124	  itemBasePremiumOf(item) * surchargeRateOf(item);
125	
126	const policyBasePremiumOf = (items: readonly Item[]): number =>
127	  sumOf(itemsGroupedByType(items), sameTypeBasePremiumOf);
128	
129	const policySurchargeOf = (items: readonly Item[]): number =>
130	  sumOf(items, itemSurchargeOf);
131	
132	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
133	
134	const firstInsuranceSurchargeOf = (basePremium: number): number =>
135	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
136	
137	const LOYALTY_DISCOUNT_RATE = 0.2;
138	const LOYALTY_YEARS_THRESHOLD = 2;
139	
140	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
142	    ? basePremium * LOYALTY_DISCOUNT_RATE
143	    : 0;
144	
145	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
146	
147	const followUpDiscountOf = (
148	  basePremium: number,
149	  previousQuoteCount: number,
150	): number =>
151	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
152	
153	const exactPremiumBeforeFeeOf = (
154	  items: readonly Item[],
155	  customer: Customer,
156	  previousQuoteCount: number,
157	): number => {
158	  const basePremium = policyBasePremiumOf(items);
159	
160	  return (
161	    basePremium +
162	    policySurchargeOf(items) +
163	    firstInsuranceSurchargeOf(basePremium) -
164	    loyaltyDiscountOf(basePremium, customer) -
165	    followUpDiscountOf(basePremium, previousQuoteCount)
166	  );
167	};
168	
169	const PROCESSING_FEE = 5;
170	
171	// Premiums round up and payouts round down: both in the MHPCO's favour.
172	const roundedPremiumInMHPCOsFavour = (premium: number): number =>
173	  Math.ceil(premium);
174	
175	const quotePremiumOf = (
176	  items: readonly Item[],
177	  customer: Customer,
178	  previousQuoteCount: number,
179	): number => {
180	  rejectUnknownItemTypes(items);
181	
182	  return roundedPremiumInMHPCOsFavour(
183	    exactPremiumBeforeFeeOf(items, customer, previousQuoteCount) +
184	      PROCESSING_FEE,
185	  );
186	};
187	
188	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
189	  sword: 1000,
190	  amulet: 600,
191	  rune: 250,
192	};
193	
194	const DEDUCTIBLE = 100;
195	const CAP_FACTOR = 2;
196	
197	const itemInsuranceValueOf = (item: Item): number =>
198	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
199	
200	const MASTER_ENCHANTMENT_THRESHOLD = 8;
201	const MASTER_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
202	const FULL_REIMBURSEMENT_RATE = 1;
203	
204	const isMasterEnchanted = (item: Item): boolean =>
205	  (item.enchantment ?? 0) >= MASTER_ENCHANTMENT_THRESHOLD;
206	
207	// Dragon material needs no branch of its own: it is reimbursed in full, which
208	// is already the default rate. Master enchantment overrides that default.
209	const reimbursementRateOf = (item: Item): number =>
210	  isMasterEnchanted(item)
211	    ? MASTER_ENCHANTMENT_REIMBURSEMENT_RATE
212	    : FULL_REIMBURSEMENT_RATE;
213	
214	// A damage entry names an item type, not a particular item, so the terms that
215	// govern it come from an insured item of that type. Absent when the policy
216	// insures no item of that type, which is what makes a damage entry uncovered.
217	const insuredItemOfType = (
218	  itemType: string,
219	  insuredItems: readonly Item[],
220	): Item | undefined => insuredItems.find((item) => item.type === itemType);
221	
222	const isCoveredBy = (itemType: string, insuredItems: readonly Item[]): boolean =>
223	  insuredItemOfType(itemType, insuredItems) !== undefined;
224	
225	const notCoveredError = (itemType: string): Error =>
226	  new Error(`Item not covered by the policy: ${itemType}`);
227	
228	// Rejects item types the policy does not insure. This also rejects item types
229	// that do not exist at all: an unknown type is, necessarily, not one the policy
230	// insures, so it needs no separate check of its own.
231	const rejectUncoveredTypes = (
232	  damages: readonly Damage[],
233	  insuredItems: readonly Item[],
234	): void => {
235	  const uncoveredDamage = damages.find(
236	    (damage) => !isCoveredBy(damage.itemType, insuredItems),
237	  );
238	
239	  if (uncoveredDamage !== undefined) {
240	    throw notCoveredError(uncoveredDamage.itemType);
241	  }
242	};
243	
244	// The reimbursement rate applies to the damage first; the deductible comes off
245	// what is left, not off the damage. Reached only after rejectInvalidDamages has
246	// established that every damaged type is one the policy insures.
247	const damagePayoutOf = (
248	  damage: Damage,
249	  insuredItems: readonly Item[],
250	): number => {
251	  const insuredItem = insuredItemOfType(damage.itemType, insuredItems);
252	
253	  if (insuredItem === undefined) {
254	    throw notCoveredError(damage.itemType);
255	  }
256	
257	  const reimbursedAmount = damage.amount * reimbursementRateOf(insuredItem);
258	
259	  return reimbursedAmount - DEDUCTIBLE;
260	};
261	
262	// The cap is twice the policy's insurance sum: the unmodified insurance values
263	// of the insured items, untouched by premium modifiers or block discounts.
264	const policyCapOf = (insuredItems: readonly Item[]): number =>
265	  sumOf(insuredItems, itemInsuranceValueOf) * CAP_FACTOR;
266	
267	const countOfType = (types: readonly string[], type: string): number =>
268	  types.filter((candidate) => candidate === type).length;
269	
270	// A damage entry claims one insured item, so a type cannot be claimed more
271	// often than the policy insures items of that type. Every damaged type is
272	// known to be covered here, so a type claimed at all is insured at least once.
273	const rejectOverclaimedTypes = (
274	  damages: readonly Damage[],
275	  insuredItems: readonly Item[],
276	): void => {
277	  const damagedTypes = damages.map((damage) => damage.itemType);
278	  const insuredTypes = insuredItems.map((item) => item.type);
279	
280	  const overclaimedType = damagedTypes.find(
281	    (type) => countOfType(damagedTypes, type) > countOfType(insuredTypes, type),
282	  );
283	
284	  if (overclaimedType !== undefined) {
285	    throw new Error(
286	      `More ${overclaimedType} damages claimed than the policy insures`,
287	    );
288	  }
289	};
290	
291	// The two checks are ordered, not independent: a type the policy does not
292	// insure at all is reported as not covered, never as overclaimed. Rejecting
293	// uncovered types first is what lets the overclaim check assume coverage.
294	const rejectInvalidDamages = (
295	  damages: readonly Damage[],
296	  insuredItems: readonly Item[],
297	): void => {
298	  rejectUncoveredTypes(damages, insuredItems);
299	  rejectOverclaimedTypes(damages, insuredItems);
300	};
301	
302	const entitledPayoutOf = (
303	  incident: Incident,
304	  insuredItems: readonly Item[],
305	): number => {
306	  rejectInvalidDamages(incident.damages, insuredItems);
307	
308	  return sumOf(incident.damages, (damage) =>
309	    damagePayoutOf(damage, insuredItems),
310	  );
311	};
312	
313	// Payouts round down and premiums round up: both in the MHPCO's favour.
314	const roundedPayoutInMHPCOsFavour = (payout: number): number =>
315	  Math.floor(payout);
316	
317	// The cap limits what a policy pays out over its lifetime, so a claim never
318	// pays more than the cap left at the time it is made.
319	const cappedBy = (entitledPayout: number, remainingCap: number): number =>
320	  Math.min(entitledPayout, remainingCap);
321	
322	const claimResultOf = (
323	  step: ClaimStep,
324	  policies: readonly QuoteStep[],
325	  remainingCap: number,
326	): ClaimResult => {
327	  const entitledPayout = entitledPayoutOf(
328	    step.incident,
329	    policies[step.policy].items,
330	  );
331	  const payout = roundedPayoutInMHPCOsFavour(
332	    cappedBy(entitledPayout, remainingCap),
333	  );
334	
335	  return { payout, remainingCap: remainingCap - payout };
336	};
337	
338	const quoteResultOf = (
339	  step: QuoteStep,
340	  customer: Customer,
341	  previousQuoteSteps: readonly QuoteStep[],
342	): QuoteResult => ({
343	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
344	});
345	
346	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
347	
348	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
349	  steps.filter(isQuoteStep);
350	
351	const quoteStepsBefore = (
352	  steps: readonly Step[],
353	  stepIndex: number,
354	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
355	
356	// The state a scenario carries from one step to the next: the results produced
357	// so far, and how much of each policy's cap is still available.
358	interface ScenarioState {
359	  readonly results: readonly StepResult[];
360	  readonly remainingCaps: readonly number[];
361	}
362	
363	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
364	  results: [],
365	  remainingCaps: policies.map((policy) => policyCapOf(policy.items)),
366	});
367	
368	const capsAfterClaim = (
369	  remainingCaps: readonly number[],
370	  policy: number,
371	  remainingCap: number,
372	): readonly number[] =>
373	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
374	
375	const stateAfterQuote = (
376	  state: ScenarioState,
377	  result: QuoteResult,
378	): ScenarioState => ({ ...state, results: [...state.results, result] });
379	
380	const stateAfterClaim = (
381	  state: ScenarioState,
382	  step: ClaimStep,
383	  result: ClaimResult,
384	): ScenarioState => ({
385	  results: [...state.results, result],
386	  remainingCaps: capsAfterClaim(
387	    state.remainingCaps,
388	    step.policy,
389	    result.remainingCap,
390	  ),
391	});
392	
393	export const runScenario = (scenario: Scenario): ScenarioResult => {
394	  const policies = quoteStepsOf(scenario.steps);
395	
396	  const { results } = scenario.steps.reduce(
397	    (state, step, stepIndex) =>
398	      isQuoteStep(step)
399	        ? stateAfterQuote(
400	            state,
401	            quoteResultOf(
402	              step,
403	              scenario.customer,
404	              quoteStepsBefore(scenario.steps, stepIndex),
405	            ),
406	          )
407	        : stateAfterClaim(
408	            state,
409	            step,
410	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
411	          ),
412	    initialStateOf(policies),
413	  );
414	
415	  return { results };
416	};
